        snowfall: () => ({ beds: [["lp_wind", 0.15, { lp: 6e3, hp: 2e3 }]], events: [ev(["k_glass2", "spk3"], 1.2, 3.5, { vol: [0.02, 0.04], rate: [1.3, 1.9], pan: [-0.8, 0.8], verb: 0.7 })] }),
