        sulfur: () => ({ beds: [["lp_boil", 0.2, { hp: 1500 }]], events: [ev(["steam1"], 2, 6, { vol: [0.05, 0.1] }), ev(["bub4", "bub5"], 0.3, 1.2, { vol: [0.04, 0.08], rate: [0.6, 1.1], lp: 2e3 })] }),
        magma: () => ({ beds: [["lp_rumble", 0.4, { lp: 300, rate: 0.6 }]], events: [ev(["gloop1", "gloop2"], 1, 3, { vol: [0.08, 0.15], rate: [0.35, 0.55], lp: 900 })] }),
