        const ledSets = [["#ff4a6b", "#4affc8", "#ffd84a"], ["#59c8ff", "#b46bff", "#4affc8"], ["#9dff4a", "#ffd84a", "#ff8a4a"]];
        const leds2 = ledSets[variant2 % ledSets.length].map((c) => m.color(c, { emissive: 1, jitter: 0 }));
