                if (p.anim === "life") fi = Math.min(F3.length - 1, Math.floor(k * F3.length));
                else if (p.anim === "loop") fi = Math.floor(p.t * p.fps + p.fr) % F3.length;
                else if (p.anim === "twinkle") fi = Math.sin(p.t * 16 + p.ph) > 0.55 ? Math.min(1, F3.length - 1) : 0;
