            turn: Math.cos(ab * DEG8),
            heading: deg < 0 ? 2 * Yc : 0,
            yawBase: 0,
            angle: clamp(-Math.atan2(u, Math.hypot(r, tw)), -0.6, 0.6) * (deg < -90 || deg > 90 ? -1 : 1),
            swimPhase: o.phase ?? 0,
            tailPhase: o.phase ?? 0,
