                let pose2 = "idle", pt = w;
                if (t > T3.cast && t < T3.cast + 0.9) {
                  pose2 = "cast";
                  pt = t - T3.cast;
                } else if (t > T3.cast + 0.9 && t < T3.strike) pose2 = "idle";
                else if (t > T3.strike && t < T3.breach) pose2 = "reel";
                else if (t > T3.logo) pose2 = "cheer";
                else if (t >= T3.boat && this.holding === "boat") pose2 = "wave";
