                const sc = s * Math.max(0.01, k) * (1 - exit * 0.6);
                const ph = age * 0.8 % 3;
                const sweepX = lerp(-40, totalW + 40, ph / 1.2) - (ox + totalW / 2 + L2.cx - L2.w / 2);
                meshes.push({ mesh, model: M4.model(p, { scale: sc, yaw: yaw0 + spin, pitch: pitch0 + Math.sin(w * 1.1 + li) * 0.06, roll: this.cam.roll || 0 }), reflect: !X.logo, k: [1.2, 1, 0.12, 1 - exit], tint: [1, 1, 1, X.logo ? clamp012(1 - (w - X.t0) * 3) * 0.6 : 0], sweep: [sweepX, 7, 1.3, 0.06], grad: [0, L2.model.ny, 0.5] });
