          if (why) return { ok: false, why };
          const fa = this.fishOf(a), fb = this.fishOf(b);
          if (!fa || !fb) return { ok: false, why: "Both fish must be in the tank." };
          fa.setState("court");
          fa.mate = fb;
          fb.setState("court");
          fb.mate = fa;
          fa.say("heart", 2);
          fb.say("heart", 2);
