          this.handleInput(dt, inp);
          this.ripples.step(dt);
          this.updateFood(dt);
          this.updateFish(dt);
          this.updateDecor(dt);
          this.updateEconomy(dt);
          this.drops.step(dt, this.shape, this.ripples);
          this.updateSnail(dt);
          this.autoCollect(dt);
          this.updateEggs(dt);
          this.updateBubbles(dt);
