          this.scene.invalidate();
          const grow3 = tier > from ? { from: [old.W / T5.W, old.H / T5.H, old.waterY / T5.waterY].map((k) => clamp(k, 0.2, 1)) } : null;
          if (grow3 && this.visibleKey === "full") this.startGrow(grow3);
