            night: this.nightK > 0.6,
            avatar: null,
            cursor: this.visibleKey === "full" && !this.build.on && this.cursor3 && this.t - this.cursor3.t < 0.5 ? this.cursor3 : null,
            onEat: (f, food) => this.onEat(f, food),
