                if (this.step === "wait" && this.t > 3.5) return { edge: true, aim: p2, action: p2, avoid: [zone], ring: p2, small: true };
                return { point: p2, aim: p2, small: this.step === "wait", bang: this.step === "hook", avoid: [zone] };
